import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, texture, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, PlaneGeometry, Mesh, Color, DoubleSide, RepeatWrapping } = THREE;

  const group = new Group();
  group.name = 'hub-features-card-3-label';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Spec colors
  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  // Atlas region 512 x 320 → aspect 1.6
  const W = 1.2;
  const H = 0.75;

  // --- Grain texture (async load, cached) ---
  const grainU = uniform(null);
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = tex.wrapT = RepeatWrapping;
      grainU.value = tex;
    });
  }

  // --- Fade-in opacity uniform ---
  const opacityU = uniform(0);

  // --- Content child group (for entrance offset) ---
  const content = new Group();

  // --- Background plane: engineered gradient + grain ---
  const bgGeo = new PlaneGeometry(W, H);
  const bgMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });

  const uvNode = uv();
  const topCol = vec3(new Color(ink));
  const botCol = vec3(new Color(surface));

  // Vertical gradient: surface at bottom, ink at top
  const grad = mix(botCol, topCol, uvNode.y);

  // Subtle grain overlay (safe when uniform null → black → mask 0.94)
  const grain = texture(grainU, uvNode.mul(3.0));
  const grainAvg = grain.r.add(grain.g).add(grain.b).mul(1.0 / 3.0);
  const grainMask = grainAvg.mul(0.06).add(0.94);

  bgMat.colorNode = grad.mul(grainMask);
  bgMat.opacityNode = opacityU;

  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.z = -0.02;
  content.add(bgMesh);

  // --- Accent bar (left edge) ---
  const accentGeo = new PlaneGeometry(0.035, H * 0.55);
  const accentMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  accentMat.colorNode = vec3(new Color(accent));
  accentMat.opacityNode = opacityU;
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-W * 0.5 + 0.05, 0, 0.001);
  content.add(accentMesh);

  // --- Text label via MSDF font atlas ---
  for (const item of items) {
    const textStr = item.text ?? '';
    const fontSize = item.typography?.fontSize ?? 39;
    const textObj = ctx.fontAtlas.createText(textStr, {
      fontSize: fontSize,
      color: paper,
      align: 'center',
    });
    textObj.position.set(0, 0, 0.002);
    content.add(textObj);
  }

  group.add(content);

  // --- Entrance animation ---
  const tl = gsap.timeline({ delay: 0.25 });
  tl.to(opacityU, { value: 0.9, duration: 0.6, ease: 'power2.out' });
  tl.from(content.position, { y: 0.12, duration: 0.6, ease: 'power2.out' }, 0);
  tl.from(content.scale, { x: 0.96, y: 0.96, duration: 0.5, ease: 'power2.out' }, 0);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    bgGeo.dispose();
    bgMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    if (grainU.value) grainU.value.dispose();
  };

  group.userData.handlers = {};

  return group;
}
